package com.ruoyi.majorpilot.content;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.majorpilot.shared.ApiException;
import java.util.*;
import java.util.regex.Pattern;

public final class TaskManifestValidator {
    private static final Pattern KEY=Pattern.compile("[a-z][a-z0-9-]{0,79}");
    public static final Set<String> PROFESSIONAL_CHECKS=Set.of("PROFESSIONAL_CORE","BEGINNER_ACCESS","DATA_CORRECTNESS","EVIDENCE_SOURCES","HINT_NO_FINAL_ANSWER","FAIRNESS","CHROME_EDGE","TIMING_45_60","RECOVERY","VERSION_CONSISTENCY");
    private TaskManifestValidator() {}
    public static void validate(JsonNode m) {
        fields(m,"schemaVersion taskVersionId contentKind majorCode demoKey versionCode title scenario goals estimatedMinutes assets steps operations reflection review");
        boolean v2=m.path("schemaVersion").asText().equals("task-manifest-v2"),v3=m.path("schemaVersion").asText().equals("task-manifest-v3"),v4=m.path("schemaVersion").asText().equals("task-manifest-v4"),v5=m.path("schemaVersion").asText().equals("task-manifest-v5");check(v2||v3||v4||v5||m.path("schemaVersion").asText().equals("task-manifest-v1"));check(m.path("taskVersionId").asText().matches("[0-7][0-9A-HJKMNP-TV-Z]{25}"));check(m.path("versionCode").asText().matches("[0-9]+\\.[0-9]+\\.[0-9]+"));
        text(m,"title",100);text(m,"scenario",1000);array(m,"goals",1,6);for(JsonNode goal:m.path("goals"))check(goal.isTextual()&&!goal.asText().isBlank()&&goal.asText().length()<=200);
        fields(m.path("estimatedMinutes"),"minimum maximum");integer(m.path("estimatedMinutes"),"minimum",1,90);integer(m.path("estimatedMinutes"),"maximum",1,90);check(m.at("/estimatedMinutes/minimum").asInt()<=m.at("/estimatedMinutes/maximum").asInt());
        String kind=m.path("contentKind").asText();check(Set.of("DEMO","MAJOR").contains(kind));
        if(kind.equals("DEMO")){check(m.path("majorCode").isNull());check(Set.of("DEMO_TABLE","DEMO_COMPARE").contains(m.path("demoKey").asText()));}
        else{check(Set.of("AI","DATA_SCIENCE","BUSINESS_ANALYTICS").contains(m.path("majorCode").asText()));check(m.path("demoKey").isNull());check(m.at("/estimatedMinutes/minimum").asInt()==45&&m.at("/estimatedMinutes/maximum").asInt()==60);}
        array(m,"assets",0,30);Map<String,JsonNode> assets=new HashMap<>();for(JsonNode a:m.path("assets")){
            fields(a,"assetKey path visibility mediaType sha256 byteLength");key(a,"assetKey");check(assets.put(a.path("assetKey").asText(),a)==null);safePath(a.path("path").asText());check(Set.of("PUBLIC","PRIVATE").contains(a.path("visibility").asText()));check(Set.of("application/json","text/csv","text/plain").contains(a.path("mediaType").asText()));check(a.path("sha256").asText().matches("[a-f0-9]{64}"));integer(a,"byteLength",1,1048576);
        }
        if(v5){check(kind.equals("MAJOR")&&Set.of("DATA_SCIENCE","BUSINESS_ANALYTICS").contains(m.path("majorCode").asText()));check(m.path("operations").isArray()&&m.path("operations").isEmpty());check(assets.containsKey("method-guide")&&assets.get("method-guide").path("visibility").asText().equals("PUBLIC"));String source=m.path("majorCode").asText().equals("DATA_SCIENCE")?"learner-activity":"weekly-funnel";check(assets.containsKey(source)&&assets.get(source).path("visibility").asText().equals("PUBLIC"));}
        if(v2){for(String name:List.of("evaluation-private","training-private","support-messages","golden-private","review-private"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PRIVATE"));for(String name:List.of("classifier-model","example-pool","practice-public","evaluation-public","baseline-summary"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PUBLIC"));}
        if(v3){check(kind.equals("MAJOR")&&m.path("majorCode").asText().equals("DATA_SCIENCE"));for(String name:List.of("canonical-events-private","golden-private","review-private"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PRIVATE"));for(String name:List.of("learner-activity","learner-activity-csv","data-dictionary","python-examples"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PUBLIC"));}
        if(v4){check(kind.equals("MAJOR")&&m.path("majorCode").asText().equals("BUSINESS_ANALYTICS"));for(String name:List.of("source-provenance-private","golden-private","review-private"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PRIVATE"));for(String name:List.of("weekly-funnel","weekly-funnel-csv","data-dictionary","business-brief","sql-examples"))check(assets.containsKey(name)&&assets.get(name).path("visibility").asText().equals("PUBLIC"));}
        array(m,"steps",1,30);Set<String> seen=new HashSet<>();Map<String,JsonNode> steps=new HashMap<>();for(JsonNode s:m.path("steps")){
            fields(s,"stepKey title instructions dependencies required responseSchemaVersion inputSchema assetKeys operationKey hints hintContextFields evidenceFields");key(s,"stepKey");String sk=s.path("stepKey").asText();check(steps.put(sk,s)==null);text(s,"title",100);text(s,"instructions",1000);text(s,"responseSchemaVersion",80);check(s.path("required").isBoolean());array(s,"dependencies",0,30);
            for(JsonNode d:s.path("dependencies"))check(d.isTextual()&&seen.contains(d.asText()));seen.add(sk);TaskInputValidator.validateSchema(s.path("inputSchema"));check(s.at("/inputSchema/type").asText().equals("object"));
            assetRefs(s,"assetKeys",assets,"PUBLIC");array(s,"hints",3,3);Set<Integer> levels=new HashSet<>();for(JsonNode hint:s.path("hints")){fields(hint,"level text");integer(hint,"level",1,3);check(levels.add(hint.path("level").asInt()));text(hint,"text",600);}
            for(String name:List.of("hintContextFields","evidenceFields")){array(s,name,0,30);for(JsonNode field:s.path(name))check(field.isTextual()&&s.at("/inputSchema/properties").has(field.asText()));}
            if(!s.path("operationKey").isNull())key(s,"operationKey");
        }
        array(m,"operations",0,30);Set<String> operations=new HashSet<>();for(JsonNode o:m.path("operations")){
            fields(o,"operationKey stepKey engineType engineVersion parametersSchema resultSchema maxEvaluations publicAssetKeys privateAssetKeys datasetAssetKey"+(v2?" modelAssetKey inputBindings":v3||v4?" inputBindings ownResponseBindings":""));key(o,"operationKey");key(o,"stepKey");check(operations.add(o.path("operationKey").asText()));JsonNode step=steps.get(o.path("stepKey").asText());check(step!=null&&step.path("operationKey").equals(o.path("operationKey")));check((v4?Set.of("BUSINESS_ANALYSIS"):v3?Set.of("DATA_ANALYSIS"):Set.of("DEMO_SUMMARY","FROZEN_CLASSIFIER","SQL_TEMPLATE","RULES")).contains(o.path("engineType").asText()));text(o,"engineVersion",80);TaskInputValidator.validateSchema(o.path("parametersSchema"));TaskInputValidator.validateSchema(o.path("resultSchema"),v2||v3||v4);integer(o,"maxEvaluations",1,30);assetRefs(o,"publicAssetKeys",assets,"PUBLIC");assetRefs(o,"privateAssetKeys",assets,"PRIVATE");check(assets.containsKey(o.path("datasetAssetKey").asText()));
            if(v2){check(o.path("engineType").asText().equals("FROZEN_CLASSIFIER")&&o.path("engineVersion").asText().equals("classifier-v1")&&o.path("maxEvaluations").asInt()==5);JsonNode model=assets.get(o.path("modelAssetKey").asText());check(model!=null&&model.path("visibility").asText().equals("PUBLIC"));check(assets.get(o.path("datasetAssetKey").asText()).path("visibility").asText().equals("PRIVATE"));array(o,"inputBindings",1,30);Set<String> bound=new HashSet<>();for(JsonNode binding:o.path("inputBindings")){fields(binding,"parameterKey sourceStepKey sourceField");String parameter=binding.path("parameterKey").asText(),source=binding.path("sourceStepKey").asText(),field=binding.path("sourceField").asText();check(bound.add(parameter));boolean dependency=false;for(JsonNode d:step.path("dependencies"))if(d.asText().equals(source))dependency=true;check(dependency&&steps.containsKey(source));check(Objects.equals(steps.get(source).at("/inputSchema/properties").get(field),o.at("/parametersSchema/properties").get(parameter))&&o.at("/parametersSchema/properties").has(parameter));}check(bound.size()==o.at("/parametersSchema/properties").size());}
            if(v3||v4){check(o.path("engineVersion").asText().equals(v4?"ba-metrics-v1":"ds-stats-v1")&&o.path("maxEvaluations").asInt()==30);check((v4?Set.of("ba-metric","ba-funnel","ba-segments"):Set.of("ds-quality-clean","ds-profile","ds-relationship","ds-stratify")).contains(o.path("operationKey").asText()));check(o.path("datasetAssetKey").asText().equals(v4?"weekly-funnel":"learner-activity")&&assets.get(o.path("datasetAssetKey").asText()).path("visibility").asText().equals("PUBLIC"));check(o.path("privateAssetKeys").isEmpty());Set<String> bound=new HashSet<>();array(o,"inputBindings",0,30);array(o,"ownResponseBindings",0,30);
                for(JsonNode binding:o.path("ownResponseBindings")){fields(binding,"parameterKey sourceField");binding(binding,step,o,bound);}
                for(JsonNode binding:o.path("inputBindings")){fields(binding,"parameterKey sourceStepKey sourceField");String source=binding.path("sourceStepKey").asText();check(steps.containsKey(source)&&ancestor(step,source,steps));binding(binding,steps.get(source),o,bound);}
                check(bound.size()==o.at("/parametersSchema/properties").size());}
            if(v4)baBindings(o);
            if(kind.equals("DEMO"))check(o.path("engineType").asText().equals("DEMO_SUMMARY"));
        }
        for(JsonNode step:steps.values())if(!step.path("operationKey").isNull())check(operations.contains(step.path("operationKey").asText()));
        if(v3)check(operations.equals(Set.of("ds-quality-clean","ds-profile","ds-relationship","ds-stratify")));
        if(v4){check(operations.equals(Set.of("ba-metric","ba-funnel","ba-segments"))&&steps.keySet().equals(Set.of("b1-context","b2-metric","b3-funnel","b4-segment","b5-hypothesis","b6-action")));for(var entry:steps.entrySet()){String expected=switch(entry.getKey()){case "b2-metric"->"ba-metric";case "b3-funnel"->"ba-funnel";case "b4-segment"->"ba-segments";default->null;};check(expected==null?entry.getValue().path("operationKey").isNull():entry.getValue().path("operationKey").asText().equals(expected));}}
        fields(m.path("reflection"),"questionSetVersion instructions inputSchema");text(m.path("reflection"),"questionSetVersion",80);text(m.path("reflection"),"instructions",1000);TaskInputValidator.validateSchema(m.at("/reflection/inputSchema"));
        JsonNode review=m.path("review");fields(review,"kind checkKeys professionalReviewRequired");check(review.path("professionalReviewRequired").isBoolean());check(review.path("professionalReviewRequired").asBoolean()==kind.equals("MAJOR"));check(review.path("kind").asText().equals(kind.equals("DEMO")?"TECHNICAL_DEMO":"PROFESSIONAL"));array(review,"checkKeys",1,30);Set<String> checks=new HashSet<>();for(JsonNode c:review.path("checkKeys"))check(c.isTextual()&&checks.add(c.asText()));if(kind.equals("MAJOR"))check(checks.containsAll(PROFESSIONAL_CHECKS));
        scan(m);
    }
    private static void baBindings(JsonNode operation){
        String key=operation.path("operationKey").asText();String step=switch(key){case "ba-metric"->"b2-metric";case "ba-funnel"->"b3-funnel";case "ba-segments"->"b4-segment";default->"";};check(operation.path("stepKey").asText().equals(step));
        var windows=Set.of("baselineStartWeek","baselineEndWeek","comparisonStartWeek","comparisonEndWeek");var metric=new HashSet<>(windows);metric.addAll(Set.of("numerator","denominator"));
        Set<String> own=key.equals("ba-metric")?metric:key.equals("ba-segments")?Set.of("segmentBy"):Set.of();var actualOwn=new HashSet<String>();
        for(var binding:operation.path("ownResponseBindings")){String field=binding.path("parameterKey").asText();check(field.equals(binding.path("sourceField").asText()));actualOwn.add(field);}check(actualOwn.equals(own));
        var expected=new HashMap<String,String>();if(key.equals("ba-funnel"))for(String field:windows)expected.put(field,"b2-metric");if(key.equals("ba-segments")){for(String field:metric)expected.put(field,"b2-metric");expected.put("focusTransitionKey","b3-funnel");}
        var actual=new HashMap<String,String>();for(var binding:operation.path("inputBindings")){String field=binding.path("parameterKey").asText();check(field.equals(binding.path("sourceField").asText()));actual.put(field,binding.path("sourceStepKey").asText());}check(actual.equals(expected));
        var required=new HashSet<String>();for(var field:operation.at("/parametersSchema/required"))required.add(field.asText());check(required.size()==operation.at("/parametersSchema/properties").size());
    }
    private static void scan(JsonNode value){if(value.isTextual()){String text=value.asText();check(!text.matches("(?is).*(https?://|file:|javascript:|<script|[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}).*"));}else for(JsonNode child:value)scan(child);}
    public static void safePath(String path){check(path.matches("[a-z0-9][a-z0-9./-]{0,200}")&&!path.contains("..")&&!path.contains("//")&&!path.endsWith("/"));}
    private static void assetRefs(JsonNode parent,String name,Map<String,JsonNode> assets,String visibility){array(parent,name,0,30);Set<String> seen=new HashSet<>();for(JsonNode ref:parent.path(name)){JsonNode a=assets.get(ref.asText());check(ref.isTextual()&&seen.add(ref.asText())&&a!=null&&a.path("visibility").asText().equals(visibility));}}
    private static boolean ancestor(JsonNode step,String source,Map<String,JsonNode> steps){for(JsonNode dependency:step.path("dependencies"))if(dependency.asText().equals(source)||ancestor(steps.get(dependency.asText()),source,steps))return true;return false;}
    private static void binding(JsonNode binding,JsonNode source,JsonNode operation,Set<String> bound){String key=binding.path("parameterKey").asText(),field=binding.path("sourceField").asText();check(key.matches("[a-zA-Z][a-zA-Z0-9_]{0,79}")&&field.matches("[a-zA-Z][a-zA-Z0-9_]{0,79}")&&bound.add(key));check(operation.at("/parametersSchema/properties").has(key)&&source.at("/inputSchema/properties").has(field)&&source.at("/inputSchema/properties").get(field).equals(operation.at("/parametersSchema/properties").get(key)));boolean targetRequired=false,sourceRequired=false;for(JsonNode k:operation.at("/parametersSchema/required"))targetRequired|=k.asText().equals(key);for(JsonNode k:source.at("/inputSchema/required"))sourceRequired|=k.asText().equals(field);check(targetRequired==sourceRequired);}
    private static void fields(JsonNode node,String keys){check(node.isObject());Set<String> allowed=Set.of(keys.split(" "));check(node.size()==allowed.size());for(String key:allowed)check(node.has(key));for(var f=node.fieldNames();f.hasNext();)check(allowed.contains(f.next()));}
    private static void text(JsonNode node,String key,int max){check(node.path(key).isTextual()&&!node.path(key).asText().isBlank()&&node.path(key).asText().length()<=max);}
    private static void key(JsonNode node,String key){check(node.path(key).isTextual()&&KEY.matcher(node.path(key).asText()).matches());}
    private static void integer(JsonNode node,String key,int min,int max){check(node.path(key).isIntegralNumber()&&node.path(key).asLong()>=min&&node.path(key).asLong()<=max);}
    private static void array(JsonNode node,String key,int min,int max){check(node.path(key).isArray()&&node.path(key).size()>=min&&node.path(key).size()<=max);}
    private static void check(boolean valid){if(!valid)throw new ApiException(422,"CONTENT_SCHEMA_INVALID");}
}
